#!/bin/bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-11-18

# Check that the agent-browser on PATH is not older than the minimum (#5289 ask b).
#
# Reads `agent-browser --version`, compares it numerically with MIN_VERSION, and
# prints one line (or one JSON object with --json). Local only, no network.
#
# MIN_VERSION below is the ONE place the minimum lives. The expect skill's prose
# floor ("Floor is `>= x.y.z`") must say the same number; tests/unit/
# test-agent-browser-version-check.mjs fails when they differ. Raise it here, then
# update that sentence in src/skills/expect/SKILL.md.
#
# Usage: check-agent-browser-version.sh [--json]
#
# Verdicts:
#   NOT_INSTALLED  no agent-browser on PATH (optional tool, never a flag)
#   UNKNOWN        --version printed nothing we can read (cannot prove a problem, never a flag)
#   OK             installed version is at or above MIN_VERSION
#   OUTDATED       installed version is below MIN_VERSION (WARN, with the upgrade command)
#
# Exit codes: 0 = NOT_INSTALLED, UNKNOWN or OK; 1 = OUTDATED; 2 = usage.
#
# Works under Git Bash on Windows: plain bash, no sort -V, no process substitution,
# no /dev/stdin, no timeout.

set -euo pipefail

MIN_VERSION="0.31.1"
UPGRADE_CMD="npm install -g agent-browser@latest"
UPGRADE_ALT="agent-browser upgrade"

OUTPUT_FORMAT="text"
while [[ $# -gt 0 ]]; do
    case "$1" in
        --json) OUTPUT_FORMAT="json"; shift ;;
        -h|--help) sed -n '3,22p' "$0"; exit 0 ;;
        *) echo "usage: check-agent-browser-version.sh [--json]" >&2; exit 2 ;;
    esac
done

emit() {
    # $1 verdict, $2 installed (may be empty), $3 text line
    if [[ "$OUTPUT_FORMAT" == "json" ]]; then
        printf '{"verdict":"%s","installed":"%s","minimum":"%s","upgrade":"%s"}\n' "$1" "$2" "$MIN_VERSION" "$UPGRADE_CMD"
    else
        printf '%s\n' "$3"
    fi
}

if ! command -v agent-browser >/dev/null 2>&1; then
    emit "NOT_INSTALLED" "" "agent-browser: NOT INSTALLED (optional; install: $UPGRADE_CMD)"
    exit 0
fi

# agent-browser --version never starts the daemon. Read it into a variable, not a pipe.
raw="$(agent-browser --version 2>&1 < /dev/null || true)"

# First x.y.z in the output ("agent-browser 0.27.1" or a bare "0.27.1").
installed=""
if [[ "$raw" =~ ([0-9]+)\.([0-9]+)\.([0-9]+) ]]; then
    installed="${BASH_REMATCH[0]}"
    i_major="${BASH_REMATCH[1]}"
    i_minor="${BASH_REMATCH[2]}"
    i_patch="${BASH_REMATCH[3]}"
fi

if [[ -z "$installed" ]]; then
    emit "UNKNOWN" "" "agent-browser: UNKNOWN version (could not read x.y.z from \`agent-browser --version\`)"
    exit 0
fi

m_major="${MIN_VERSION%%.*}"
m_rest="${MIN_VERSION#*.}"
m_minor="${m_rest%%.*}"
m_patch="${m_rest#*.}"

# Numeric compare, field by field (10# so a leading zero is never read as octal).
outdated=0
if (( 10#$i_major < 10#$m_major )); then
    outdated=1
elif (( 10#$i_major == 10#$m_major )); then
    if (( 10#$i_minor < 10#$m_minor )); then
        outdated=1
    elif (( 10#$i_minor == 10#$m_minor )) && (( 10#$i_patch < 10#$m_patch )); then
        outdated=1
    fi
fi

if (( outdated )); then
    emit "OUTDATED" "$installed" "agent-browser: WARN $installed is older than the minimum $MIN_VERSION. Upgrade: $UPGRADE_CMD (or: $UPGRADE_ALT)"
    exit 1
fi

emit "OK" "$installed" "agent-browser: OK $installed (minimum $MIN_VERSION)"
exit 0
